def initialize(path):
    path=Path(path); original=path.read_bytes()
    if b'<!-- SKILLS:ROWS:START -->' in original:
        return False
    if hashlib.sha256(original).hexdigest()!=OLD_SHA256:
        raise ValueError('Unknown unmarked webpage: manual review required; no write')
    text=original.decode('utf-8')
    for before, after in REPLACEMENTS:
        if not before or text.count(before)!=1: raise ValueError('Migration pattern mismatch')
        text=text.replace(before,after,1)
    output=text.encode('utf-8')
    if hashlib.sha256(output).hexdigest()!=NEW_SHA256: raise ValueError('Migration output mismatch')
    fd,tmp=tempfile.mkstemp(prefix='.skills-init-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as f: f.write(output)
        os.chmod(tmp,path.stat().st_mode & 0o777)
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)
    return True
